package com.metaverse.coin.strategy.htx.persistence;

import com.metaverse.coin.strategy.htx.controller.HtxTrendExitV5Controller;
import com.metaverse.coin.strategy.htx.service.HtxTrendExitObserverV5;
import com.metaverse.coin.strategy.htx.service.HtxTrendExitV5QueryService;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.context.ApplicationContext;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.jdbc.core.JdbcTemplate;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.List;
import static com.metaverse.coin.strategy.htx.persistence.HtxTrendExitStateStoreV5.*;
import static com.metaverse.coin.strategy.htx.service.HtxTrendExitContractV5.*;
import static com.metaverse.coin.strategy.htx.service.HtxTrendExitKernelV5.decide;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest
class HtxTrendExitStateStoreV5Test {
 @Autowired HtxTrendExitStateStoreV5 store;@Autowired HtxTrendExitObserverV5 observer;@Autowired HtxTrendExitV5QueryService query;@Autowired JdbcTemplate jdbc;@Autowired ApplicationContext context;
 final Policy policy=defaultPolicy();final LocalDateTime now=LocalDateTime.of(2026,10,10,1,30);
 @BeforeEach void clean(){for(String table:new String[]{"htx_trend_exit_fill_v5","htx_trend_exit_intent_v5","htx_trend_exit_decision","htx_trend_exit_state_v5","htx_trend_entry_contract","htx_trend_exit_owner_lease_v5","htx_trend_reentry_guard_v5","htx_trend_position"})jdbc.update("DELETE FROM "+table);}
 @Test void appendIsAtomicIdempotentAndCreatesOneIntent(){Setup s=setup(41);assertEquals(AppendStatus.APPLIED,store.compareAndAppend(s.request));assertEquals(AppendStatus.IDEMPOTENT,store.compareAndAppend(s.request));assertEquals(1,count("htx_trend_exit_decision"));assertEquals(1,count("htx_trend_exit_intent_v5"));assertEquals(clientOrderId(s.key),jdbc.queryForObject("SELECT client_order_id FROM htx_trend_exit_intent_v5 WHERE decision_key=?",String.class,s.key));}
 @Test void decisionFailureRollsBackStateAndIntent(){Setup s=setup(42);AppendRequest bad=new AppendRequest(42,1,0,s.lease.ownerToken(),s.event.event_key(),s.key,null,"BTC-USDT",new BigDecimal("6"),s.contract,policy,State.initial(),s.event,s.transition,true,now);assertThrows(DataIntegrityViolationException.class,()->store.compareAndAppend(bad));assertEquals(0L,store.revision(42));assertEquals(0,count("htx_trend_exit_decision"));assertEquals(0,count("htx_trend_exit_intent_v5"));}
 @Test void expiredOwnerIsFenced(){Setup s=setup(43,100,State.initial());Lease takeover=store.claim(scopeKey(s.contract),"worker-b",now.plusSeconds(1),60_000);assertEquals(s.lease.ownerToken()+1,takeover.ownerToken());assertEquals(AppendStatus.FENCED,store.compareAndAppend(s.request));}
 @Test void reconciledTakeoverCanAdoptMonotonicToken(){Setup s=setup(45,100,State.initial());Lease takeover=store.claim(scopeKey(s.contract),"worker-b",now.plusSeconds(1),60_000);assertTrue(store.adoptOwner(s.contract,45,1,s.lease.ownerToken(),takeover.ownerToken(),now.plusSeconds(1)));}
 @Test void uniqueFillsAdvanceQuantityOnceAndCloseAtTarget(){Setup s=setup(44);store.compareAndAppend(s.request);long id=store.intentId(s.key);FillRequest first=new FillRequest(id,7,44,1,"o1","t1",new BigDecimal("2"),new BigDecimal("95"),new BigDecimal(".1"),new BigDecimal(".03"),BigDecimal.ZERO,now.plusSeconds(1));assertEquals(0,new BigDecimal("4").compareTo(store.applyUniqueFill(first).confirmedQty()));assertEquals(FillStatus.IDEMPOTENT,store.applyUniqueFill(first).status());FillResult done=store.applyUniqueFill(new FillRequest(id,7,44,1,"o1","t2",new BigDecimal("4"),new BigDecimal("94.9"),new BigDecimal(".2"),new BigDecimal(".07"),BigDecimal.ZERO,now.plusSeconds(2)));assertEquals(0,BigDecimal.ZERO.compareTo(done.confirmedQty()));assertEquals(2,count("htx_trend_exit_fill_v5"));}
 @Test void reentryLockUsesAccountSymbolSideBudget(){assertEquals(AppendStatus.APPLIED,store.updateReentryGuard(new GuardUpdate(7,"TREND","BTC-USDT","LONG","structure-a",-1,0,new BigDecimal("8"),new BigDecimal("2"),"MODEL_INVALIDATION","LOCKED","{}",now)));assertFalse(store.evaluateReentry(7,"TREND","BTC-USDT","LONG","structure-a",new BigDecimal("20"),false).allowed());assertEquals("ACCOUNT_SYMBOL_SIDE_BUDGET_EXHAUSTED",store.evaluateReentry(7,"TREND","BTC-USDT","LONG","structure-b",new BigDecimal("10"),false).reason());}
 @Test void observePersistsExplanationWithoutIntentAndRejectsLive(){Setup s=setup(46);var request=new HtxTrendExitObserverV5.ObservationRequest("OBSERVE",46,1,0,s.lease.ownerToken(),"primary","BTC-USDT",new BigDecimal("6"),s.contract,State.initial(),s.event,policy,now);assertEquals(Action.FULL_CLOSE,observer.observe(request).transition().decision().action());assertEquals(0,count("htx_trend_exit_intent_v5"));assertThrows(IllegalArgumentException.class,()->observer.observe(new HtxTrendExitObserverV5.ObservationRequest("LIVE",46,1,1,s.lease.ownerToken(),"primary","BTC-USDT",new BigDecimal("6"),s.contract,s.transition.state(),s.event,policy,now)));}
 @Test void readModelIsAccountScopedAndDisabledByDefault(){Setup s=setup(47);observer.observe(new HtxTrendExitObserverV5.ObservationRequest("OBSERVE",47,1,0,s.lease.ownerToken(),"primary","BTC-USDT",new BigDecimal("6"),s.contract,State.initial(),s.event,policy,now));var view=query.get(47,"primary");assertEquals(VERSION,view.engineVersion());assertEquals(policy.maturity_bars(),view.requiredBars());assertEquals(policy.soft_breach_confirm_bars(),view.requiredBreachBars());assertTrue(view.accountingComplete());assertThrows(IllegalArgumentException.class,()->query.get(47,"other"));assertTrue(context.getBeansOfType(HtxTrendExitV5Controller.class).isEmpty());}
 @Test void tamperedDecisionInputHashIsRejected(){Setup s=setup(49);Decision d=s.transition.decision();Decision tampered=new Decision(d.action(),d.phase(),d.target_remaining_contracts(),d.reason_codes(),d.evidence_groups(),"0".repeat(64),d.active_soft_boundary(),d.pending_soft_boundary(),d.eligible_bars(),d.soft_breach_bars());AppendRequest bad=new AppendRequest(49,1,0,s.lease.ownerToken(),s.event.event_key(),s.key,"primary","BTC-USDT",new BigDecimal("6"),s.contract,policy,State.initial(),s.event,new Transition(tampered,s.transition.state()),true,now);assertThrows(IllegalArgumentException.class,()->store.compareAndAppend(bad));}
 @Test void hardRiskDuringPendingPartialDoesNotCreateSecondIntent(){State prior=new State(0,ProfitPhase.BUILDING,ExecutionState.IDLE,900000L,2,0,new BigDecimal("105"),null,null,null,null,0,null,0,false);Setup s=setup(48,60_000,prior);Event target=new Event("bar:partial",EventKind.CLOSED_BAR,1800000,new BigDecimal("110"),6,"COMPLETE",true,900000L,1800000L,new BigDecimal("110"),BigDecimal.ONE,new BigDecimal("5"),new BigDecimal(".1"),ModelState.VALID,List.of("E-H"),true,new BigDecimal("1"));Transition partial=decide(s.contract,prior,target,policy);AppendRequest first=new AppendRequest(48,1,0,s.lease.ownerToken(),target.event_key(),decisionKey(48,1,target.event_key(),s.contract.policy_hash()),"primary","BTC-USDT",new BigDecimal("6"),s.contract,policy,prior,target,partial,true,now);assertEquals(AppendStatus.APPLIED,store.compareAndAppend(first));Event hard=event("tick:hard");Transition full=decide(s.contract,partial.state(),hard,policy);AppendRequest second=new AppendRequest(48,1,1,s.lease.ownerToken(),hard.event_key(),decisionKey(48,1,hard.event_key(),s.contract.policy_hash()),"primary","BTC-USDT",new BigDecimal("6"),s.contract,policy,partial.state(),hard,full,true,now.plusSeconds(1));assertEquals(AppendStatus.APPLIED,store.compareAndAppend(second));assertEquals(1,count("htx_trend_exit_intent_v5"));assertEquals("RECONCILE_PENDING_INTENT",jdbc.queryForObject("SELECT execution_readiness FROM htx_trend_exit_decision WHERE decision_key=?",String.class,second.decisionKey()));assertEquals(new BigDecimal("2"),pendingDelta(new BigDecimal("6"),BigDecimal.ZERO,new BigDecimal("2"),new BigDecimal("2")));}
 private Setup setup(long id){return setup(id,60_000,State.initial());}private Setup setup(long id,long leaseMs,State initial){jdbc.update("INSERT INTO htx_trend_position(id,position_key,contract_code,status,side,contract_size,contract_volume,remaining_contract_volume,leverage,account_id,account_label) VALUES(?,?,?,?,?,?,?,?,?,?,?)",id,"v5-pos-"+id,"BTC-USDT","OPEN","LONG",BigDecimal.ONE,6,6,5,7,"primary");EntryThesis contract=contract();Lease lease=store.claim(scopeKey(contract),"worker-a",now,leaseMs);store.initialize(new InitializeRequest(id,1,7,lease.ownerToken(),"primary",new BigDecimal("6"),contract,policy,initial));Event event=event("tick:"+id);Transition transition=decide(contract,initial,event,policy);String key=decisionKey(id,1,event.event_key(),contract.policy_hash());return new Setup(contract,lease,event,transition,key,new AppendRequest(id,1,initial.revision(),lease.ownerToken(),event.event_key(),key,"primary","BTC-USDT",new BigDecimal("6"),contract,policy,initial,event,transition,true,now));}
 private EntryThesis contract(){return new EntryThesis(7,"primary",1,"FIB_PULLBACK_CONTINUATION","fib:btc:1",Side.LONG,900,0,new BigDecimal("100"),6,BigDecimal.ONE,new BigDecimal("95"),new BigDecimal("97"),new BigDecimal("110"),BigDecimal.ONE,new BigDecimal(".1"),VERSION,"trend-entry-thesis-v5","trend-model-holding-v5",canonicalHash(policy));}
 private Event event(String key){return new Event(key,EventKind.TICK,1,new BigDecimal("95"),6,"COMPLETE",true,null,null,null,null,BigDecimal.ZERO,new BigDecimal(".1"),ModelState.UNKNOWN,List.of(),false,null);}
 private int count(String table){return jdbc.queryForObject("SELECT COUNT(*) FROM "+table,Integer.class);}
 private record Setup(EntryThesis contract,Lease lease,Event event,Transition transition,String key,AppendRequest request){}
}
